"""
Render the real MuJoCo scene from multiple camera poses and overlay cube pose data.

This script does not modify scene_box.xml. It moves the existing track_cam camera
in memory, renders MuJoCo images, projects where the ArUco marker would be on the
cube top face, estimates the cube pose from these projected corners, and writes
the coordinates directly on each rendered frame.
"""

import os
import xml.etree.ElementTree as ET

import cv2
import matplotlib.pyplot as plt
import mujoco
import numpy as np


# Generated by GitHub Copilot
def load_cube_center_from_scene(scene_path):
    """Load fixed cube center from scene XML."""
    if not os.path.exists(scene_path):
        raise FileNotFoundError(f"Scene file not found: {scene_path}")

    root = ET.parse(scene_path).getroot()
    cube_body = root.find(".//worldbody/body[@name='object']")
    if cube_body is None:
        raise ValueError("Cube body named 'object' not found in scene XML")

    values = [float(value) for value in cube_body.get("pos", "0 0 0").split()]
    if len(values) != 3:
        raise ValueError("Cube position must have exactly 3 values")
    return np.array(values, dtype=np.float64)


# Generated by GitHub Copilot
def make_lookat_camera_axes(camera_pos_w, target_w, world_up=np.array([0.0, 0.0, 1.0])):
    """
    Build camera axes in world frame.

    Returns right, up, forward axes, all expressed in world coordinates.
    """
    forward = target_w - camera_pos_w
    forward = forward / np.linalg.norm(forward)

    right = np.cross(forward, world_up)
    right = right / np.linalg.norm(right)

    up = np.cross(right, forward)
    up = up / np.linalg.norm(up)
    return right, up, forward


# Generated by GitHub Copilot
def rotation_world_to_camera_opencv(camera_pos_w, target_w):
    """Build OpenCV-style world->camera rotation and translation."""
    right, up, forward = make_lookat_camera_axes(camera_pos_w, target_w)
    r_wc_cv = np.column_stack((right, up, forward))
    r_cw_cv = r_wc_cv.T
    t_cw_cv = -r_cw_cv @ camera_pos_w.reshape(3, 1)
    return r_cw_cv, t_cw_cv


# Generated by GitHub Copilot
def mujoco_quat_from_lookat(camera_pos_w, target_w):
    """
    Build a MuJoCo camera quaternion in w,x,y,z order.

    MuJoCo camera local axes are X=right, Y=up, Z=backward, so the third axis in
    world coordinates is -forward.
    """
    right, up, forward = make_lookat_camera_axes(camera_pos_w, target_w)
    rot_wc_mj = np.column_stack((right, up, -forward))
    rot_flat = rot_wc_mj.reshape(-1).astype(np.float64)
    quat = np.zeros(4, dtype=np.float64)
    mujoco.mju_mat2Quat(quat, rot_flat)
    return quat


# Generated by GitHub Copilot
def intrinsics_from_mujoco_fovy(width, height, fovy_deg):
    """Convert MuJoCo vertical FOV into an OpenCV intrinsics matrix."""
    fy = 0.5 * height / np.tan(np.deg2rad(fovy_deg) * 0.5)
    fx = fy
    cx = width / 2.0
    cy = height / 2.0
    return np.array([[fx, 0.0, cx], [0.0, fy, cy], [0.0, 0.0, 1.0]], dtype=np.float32)


# Generated by GitHub Copilot
def detect_marker_corners(frame_bgr, marker_id=42):
    """Detect one ArUco marker and return its 2D corners if found."""
    gray = cv2.cvtColor(frame_bgr, cv2.COLOR_BGR2GRAY)
    aruco_dict = cv2.aruco.getPredefinedDictionary(cv2.aruco.DICT_6X6_250)
    params = cv2.aruco.DetectorParameters()
    params.adaptiveThreshWinSizeMin = 3
    params.adaptiveThreshWinSizeMax = 31
    params.adaptiveThreshWinSizeStep = 4
    params.cornerRefinementMethod = cv2.aruco.CORNER_REFINE_SUBPIX
    detector = cv2.aruco.ArucoDetector(aruco_dict, params)

    corners, ids, _ = detector.detectMarkers(gray)
    if ids is None or len(ids) == 0:
        return None, corners, ids

    for idx, detected_id in enumerate(ids.flatten()):
        if int(detected_id) == int(marker_id):
            return corners[idx][0].astype(np.float32), corners, ids

    return None, corners, ids


# Generated by GitHub Copilot
def render_mujoco_views(scene_path, output_path, width=1280, height=960, num_views=8):
    """Render multiple MuJoCo views with projected marker and estimated coordinates."""
    model = mujoco.MjModel.from_xml_path(scene_path)
    data = mujoco.MjData(model)
    renderer = mujoco.Renderer(model, height=height, width=width)

    cam_id = mujoco.mj_name2id(model, mujoco.mjtObj.mjOBJ_CAMERA, "track_cam")
    if cam_id < 0:
        raise ValueError("Camera 'track_cam' not found in scene")

    cube_center_w = load_cube_center_from_scene(scene_path)
    cube_half_height = 0.02
    marker_center_w = cube_center_w + np.array([0.0, 0.0, cube_half_height], dtype=np.float64)

    marker_size_m = 0.04
    half = marker_size_m / 2.0
    marker_local = np.array(
        [[-half, half, 0.0], [half, half, 0.0], [half, -half, 0.0], [-half, -half, 0.0]],
        dtype=np.float32,
    )
    marker_world = marker_local.astype(np.float64) + marker_center_w

    fovy = float(model.cam_fovy[cam_id])
    camera_matrix = intrinsics_from_mujoco_fovy(width, height, fovy)
    dist = np.zeros((4, 1), dtype=np.float32)

    radius = 0.34
    base_z = 0.40
    cols = 4
    rows = int(np.ceil(num_views / cols))
    fig, axes = plt.subplots(rows, cols, figsize=(16, 4 * rows))
    axes = np.array(axes).reshape(rows, cols)
    detected_count = 0

    for view_idx in range(num_views):
        theta = (2.0 * np.pi * view_idx) / num_views
        cam_pos = np.array(
            [
                cube_center_w[0] + radius * np.cos(theta),
                cube_center_w[1] + radius * np.sin(theta),
                base_z + 0.05 * np.sin(2.0 * theta),
            ],
            dtype=np.float64,
        )

        model.cam_pos[cam_id] = cam_pos
        model.cam_quat[cam_id] = mujoco_quat_from_lookat(cam_pos, marker_center_w)
        mujoco.mj_forward(model, data)

        renderer.update_scene(data, camera=cam_id)
        frame_rgb = renderer.render().copy()
        frame = cv2.cvtColor(frame_rgb, cv2.COLOR_RGB2BGR)

        # Project marker corners consistently with the same camera pose.
        r_cw_cv, t_cw_cv = rotation_world_to_camera_opencv(cam_pos, marker_center_w)
        rvec_gt, _ = cv2.Rodrigues(r_cw_cv)
        img_pts_proj, _ = cv2.projectPoints(marker_world, rvec_gt, t_cw_cv, camera_matrix, dist)
        img_pts_proj = img_pts_proj.reshape(-1, 2).astype(np.float32)

        detected_pts, all_corners, all_ids = detect_marker_corners(frame, marker_id=42)
        use_detected = detected_pts is not None
        img_pts = detected_pts if use_detected else img_pts_proj

        if all_ids is not None and len(all_ids) > 0:
            cv2.aruco.drawDetectedMarkers(frame, all_corners, all_ids)

        ok, rvec_est, tvec_est = cv2.solvePnP(
            marker_local,
            img_pts,
            camera_matrix,
            dist,
            flags=cv2.SOLVEPNP_ITERATIVE,
        )
        if not ok:
            continue

        if use_detected:
            detected_count += 1

        cube_cam = tvec_est.reshape(3) - np.array([0.0, 0.0, cube_half_height], dtype=np.float64)
        marker_center_w_est = (r_cw_cv.T @ tvec_est.reshape(3, 1)).reshape(3) + cam_pos
        cube_est_w = marker_center_w_est - np.array([0.0, 0.0, cube_half_height], dtype=np.float64)
        err = np.linalg.norm(cube_est_w - cube_center_w)

        pts = np.round(img_pts).astype(np.int32)
        x0 = max(int(np.min(pts[:, 0])) - 20, 0)
        y0 = max(int(np.min(pts[:, 1])) - 20, 0)
        x1 = min(int(np.max(pts[:, 0])) + 20, width - 1)
        y1 = min(int(np.max(pts[:, 1])) + 20, height - 1)

        cv2.rectangle(frame, (x0, y0), (x1, y1), (0, 220, 255), 2)
        cv2.drawFrameAxes(frame, camera_matrix, dist, rvec_est, tvec_est, marker_size_m * 0.5)

        crop = frame[y0:y1, x0:x1].copy()
        if crop.size > 0:
            zoom = cv2.resize(crop, (180, 180), interpolation=cv2.INTER_NEAREST)
            zh, zw = zoom.shape[:2]
            inset_x0 = width - zw - 12
            inset_y0 = 12
            frame[inset_y0:inset_y0 + zh, inset_x0:inset_x0 + zw] = zoom
            cv2.rectangle(frame, (inset_x0, inset_y0), (inset_x0 + zw, inset_y0 + zh), (255, 255, 255), 2)
            cv2.putText(frame, "zoom marker", (inset_x0, inset_y0 + zh + 18), cv2.FONT_HERSHEY_SIMPLEX, 0.5, (255, 255, 255), 1, cv2.LINE_AA)

        status_text = "detected" if use_detected else "fallback-proj"
        status_color = (80, 255, 80) if use_detected else (0, 220, 255)
        cv2.putText(frame, f"view {view_idx:02d}", (14, 26), cv2.FONT_HERSHEY_SIMPLEX, 0.7, (255, 255, 255), 2, cv2.LINE_AA)
        cv2.putText(frame, f"aruco: {status_text}", (14, 52), cv2.FONT_HERSHEY_SIMPLEX, 0.65, status_color, 2, cv2.LINE_AA)
        cv2.putText(frame, f"err={err:.2e} m", (14, height - 96), cv2.FONT_HERSHEY_SIMPLEX, 0.6, (255, 255, 255), 2, cv2.LINE_AA)
        cv2.putText(frame, f"true_w: ({cube_center_w[0]:+.3f}, {cube_center_w[1]:+.3f}, {cube_center_w[2]:+.3f}) m", (14, height - 72), cv2.FONT_HERSHEY_SIMPLEX, 0.6, (80, 255, 80), 2, cv2.LINE_AA)
        cv2.putText(frame, f"est_w:  ({cube_est_w[0]:+.3f}, {cube_est_w[1]:+.3f}, {cube_est_w[2]:+.3f}) m", (14, height - 48), cv2.FONT_HERSHEY_SIMPLEX, 0.6, (80, 80, 255), 2, cv2.LINE_AA)
        cv2.putText(frame, f"cube_cam:({cube_cam[0]:+.3f}, {cube_cam[1]:+.3f}, {cube_cam[2]:+.3f}) m", (14, height - 24), cv2.FONT_HERSHEY_SIMPLEX, 0.6, (230, 120, 255), 2, cv2.LINE_AA)

        rgb = cv2.cvtColor(frame, cv2.COLOR_BGR2RGB)
        ax = axes[view_idx // cols, view_idx % cols]
        ax.imshow(rgb)
        ax.axis("off")

    for idx in range(num_views, rows * cols):
        axes[idx // cols, idx % cols].axis("off")

    fig.suptitle(
        f"MuJoCo ArUco detection: {detected_count}/{num_views} views detected",
        fontsize=14,
    )
    fig.tight_layout()
    fig.savefig(output_path, dpi=150)
    plt.close(fig)


# Generated by GitHub Copilot
def main():
    """Generate a MuJoCo visualization grid for cube pose estimation."""
    # Generated by GitHub Copilot
    aruco_dir = os.path.dirname(os.path.abspath(__file__))
    scene_path = os.path.join(aruco_dir, "scene_box_aruco.xml")
    output_path = os.path.join(aruco_dir, "mujoco_cube_pose_views.png")

    render_mujoco_views(scene_path, output_path)
    print(f"MuJoCo visualization saved: {output_path}")


if __name__ == "__main__":
    main()
